cd /work/output/artifacts/skill-flow-bellevue-weather-simulated/BellevueWeather/BellevueWeather \
  && python3 << 'EOF'
import json

with open('BellevueWeather.flow') as f:
    d = json.load(f)

# Keep only trigger and connector definitions; we'll add end and script definitions
trigger_def = next(x for x in d['definitions'] if x['nodeType'] == 'core.trigger.manual')
connector_def = next(x for x in d['definitions'] if x['nodeType'] == 'uipath.connector.custom-codereval-openmeteoapis.getcurrentweather')

# Script node definition (from registry get output captured earlier)
script_def = {
    "nodeType": "core.action.script",
    "version": "1.0",
    "category": "data-operations",
    "description": "Run custom JavaScript code",
    "tags": ["code", "javascript", "python"],
    "sortOrder": 35,
    "supportsErrorHandling": True,
    "display": {"label": "Script", "icon": "code"},
    "handleConfiguration": [
        {"position": "left", "handles": [{"id": "input", "type": "target", "handleType": "input"}]},
        {"position": "right", "handles": [
            {"id": "success", "type": "source", "handleType": "output"},
            {"id": "error", "label": "Error", "type": "source", "handleType": "output",
             "visible": "{inputs.errorHandlingEnabled}", "constraints": {"maxConnections": 1}}
        ]}
    ],
    "debug": {"runtime": "clientScript"},
    "model": {"type": "bpmn:ScriptTask"},
    "inputDefinition": {
        "type": "object",
        "properties": {"script": {"type": "string", "minLength": 1}},
        "required": ["script"]
    },
    "inputDefaults": {"script": ""},
    "outputDefinition": {
        "output": {"type": "object", "description": "The return value of the script", "source": "=result.response", "var": "output"},
        "error": {"type": "object", "description": "Error information if the node fails", "source": "=Error", "var": "error"}
    }
}

# End node definition
end_def = {
    "nodeType": "core.control.end",
    "version": "1.0",
    "category": "control-flow",
    "description": "Mark the end of a workflow path",
    "tags": ["control-flow", "end", "finish", "complete"],
    "sortOrder": 20,
    "display": {"label": "End", "icon": "circle-check", "shape": "circle"},
    "handleConfiguration": [
        {"position": "left", "handles": [{"id": "input", "type": "target", "handleType": "input"}]}
    ],
    "model": {"type": "bpmn:EndEvent"},
    "runtimeConstraints": {"exclude": ["api-function"]}
}

# Weather evaluation script
weather_script = """var w = $vars.getCurrentWeather1.output && $vars.getCurrentWeather1.output.current_weather;
if (!w) {
  return { isNiceDay: false, message: "Could not retrieve weather data for Bellevue, WA." };
}
var temp = w.temperature;
var windspeed = w.windspeed;
var weathercode = w.weathercode;
// WMO weather code: 0=clear, 1-3=mainly clear/partly cloudy, 45/48=fog
// 51-67=drizzle/rain, 71-77=snow, 80-82=rain showers, 95+=thunderstorm
var isSunny = weathercode >= 0 && weathercode <= 3;
var isWarm = temp >= 15 && temp <= 28;
var isCalmWind = windspeed < 30;
var isNiceDay = isSunny && isWarm && isCalmWind;
var conditions = [];
if (!isSunny) conditions.push("cloudy or rainy (weather code " + weathercode + ")");
if (!isWarm) conditions.push("temperature " + temp + "°C is outside the comfortable range");
if (!isCalmWind) conditions.push("wind speed " + windspeed + " km/h is too high");
var message;
if (isNiceDay) {
  message = "It's a nice day in Bellevue, WA! Temperature: " + temp + "°C, wind: " + windspeed + " km/h, clear skies.";
} else {
  message = "Not the nicest day in Bellevue, WA. " + conditions.join("; ") + ".";
}
return { isNiceDay: isNiceDay, temperature: temp, windspeed: windspeed, weathercode: weathercode, message: message };"""

d['nodes'] = [
    # keep start
    next(n for n in d['nodes'] if n['id'] == 'start'),
    # keep connector node
    next(n for n in d['nodes'] if n['id'] == 'getCurrentWeather1'),
    # new script node
    {
        "id": "evaluateWeather1",
        "type": "core.action.script",
        "typeVersion": "1.0",
        "display": {"label": "Evaluate Weather"},
        "inputs": {"script": weather_script}
    },
    # new end node
    {
        "id": "end1",
        "type": "core.control.end",
        "typeVersion": "1.0",
        "display": {"label": "End"}
    }
]

d['edges'] = [
    {"id": "edge-start-weather", "source": "start", "sourceHandle": "output", "target": "getCurrentWeather1", "targetPort": "input"},
    {"id": "edge-weather-evaluate", "source": "getCurrentWeather1", "sourceHandle": "output", "target": "evaluateWeather1", "targetPort": "input"},
    {"id": "edge-evaluate-end", "source": "evaluateWeather1", "sourceHandle": "success", "target": "end1", "targetPort": "input"}
]

d['definitions'] = [trigger_def, connector_def, script_def, end_def]

# variables.nodes - keep start.output and connector outputs, add script outputs
d['variables'] = {
    "nodes": [
        {"id": "start.output", "type": "object", "description": "Data passed when manually triggering the workflow.", "binding": {"nodeId": "start", "outputId": "output"}},
        {"id": "getCurrentWeather1.output", "type": "object", "description": "Weather data from Open-Meteo", "binding": {"nodeId": "getCurrentWeather1", "outputId": "output"}},
        {"id": "getCurrentWeather1.error", "type": "object", "binding": {"nodeId": "getCurrentWeather1", "outputId": "error"}},
        {"id": "evaluateWeather1.output", "type": "object", "description": "Weather evaluation result", "binding": {"nodeId": "evaluateWeather1", "outputId": "output"}},
        {"id": "evaluateWeather1.error", "type": "object", "binding": {"nodeId": "evaluateWeather1", "outputId": "error"}}
    ]
}

d['layout'] = {
    "nodes": {
        "start": {"position": {"x": 64, "y": 144}},
        "getCurrentWeather1": {"position": {"x": 0, "y": 0}},
        "evaluateWeather1": {"position": {"x": 0, "y": 0}},
        "end1": {"position": {"x": 0, "y": 0}}
    }
}

with open('BellevueWeather.flow', 'w') as f:
    json.dump(d, f, indent=2)
print("Done")
EOF

