&& python3 << 'EOF'
import json

with open('BellevueWeather.flow') as f:
    d = json.load(f)

# Keep start, evaluateWeather1, end1, and new http node; drop connector node
start_node = next(n for n in d['nodes'] if n['id'] == 'start')
http_node = next(n for n in d['nodes'] if n['id'] == 'fetchWeatherOpenMeteo1')
eval_node = next(n for n in d['nodes'] if n['id'] == 'evaluateWeather1')
end_node = next(n for n in d['nodes'] if n['id'] == 'end1')

# Updated script: user's rule — temp in Celsius from API, convert to F, > 60F = nice
new_script = """var w = $vars.fetchWeatherOpenMeteo1.output && $vars.fetchWeatherOpenMeteo1.output.body && $vars.fetchWeatherOpenMeteo1.output.body.current_weather;
if (!w) {
  return { isNiceDay: false, message: "Could not retrieve weather data for Bellevue, WA." };
}
var tempC = w.temperature;
var tempF = (tempC * 9 / 5) + 32;
var isNiceDay = tempF > 60;
var message;
if (isNiceDay) {
  message = "It's a nice day in Bellevue, WA! Temperature is " + tempF.toFixed(1) + "°F (" + tempC.toFixed(1) + "°C) — above 60°F.";
} else {
  message = "Not a nice day in Bellevue, WA. Temperature is " + tempF.toFixed(1) + "°F (" + tempC.toFixed(1) + "°C) — at or below 60°F.";
}
return { isNiceDay: isNiceDay, temperatureF: Math.round(tempF * 10) / 10, temperatureC: tempC, message: message };"""

eval_node['inputs']['script'] = new_script

d['nodes'] = [start_node, http_node, eval_node, end_node]

d['edges'] = [
    {'id': 'edge-start-http',      'sourceNodeId': 'start',                 'sourcePort': 'output',  'targetNodeId': 'fetchWeatherOpenMeteo1', 'targetPort': 'input'},
    {'id': 'edge-http-evaluate',   'sourceNodeId': 'fetchWeatherOpenMeteo1','sourcePort': 'default', 'targetNodeId': 'evaluateWeather1',       'targetPort': 'input'},
    {'id': 'edge-evaluate-end',    'sourceNodeId': 'evaluateWeather1',      'sourcePort': 'success', 'targetNodeId': 'end1',                   'targetPort': 'input'}
]

# Keep trigger + http + script + end definitions; drop connector definition
trigger_def  = next(x for x in d['definitions'] if x['nodeType'] == 'core.trigger.manual')
http_def     = next(x for x in d['definitions'] if x['nodeType'] == 'core.action.http.v2')
script_def   = next(x for x in d['definitions'] if x['nodeType'] == 'core.action.script')
end_def      = next(x for x in d['definitions'] if x['nodeType'] == 'core.control.end')
d['definitions'] = [trigger_def, http_def, script_def, end_def]

# Remove connector bindings; keep any others (there may be none left)
d['bindings'] = [b for b in d.get('bindings', []) if 'custom-codereval-openmeteoapis' not in b.get('name', '') and 'custom-codereval-openmeteoapis' not in b.get('resourceKey', '')]

# variables.nodes: rebuild for current nodes
d['variables'] = {
    'nodes': [
        {'id': 'start.output',                  'type': 'object', 'description': 'Manual trigger payload',       'binding': {'nodeId': 'start',                 'outputId': 'output'}},
        {'id': 'fetchWeatherOpenMeteo1.output',  'type': 'object', 'description': 'HTTP response from Open-Meteo','binding': {'nodeId': 'fetchWeatherOpenMeteo1', 'outputId': 'output'}},
        {'id': 'fetchWeatherOpenMeteo1.error',   'type': 'object', 'binding': {'nodeId': 'fetchWeatherOpenMeteo1', 'outputId': 'error'}},
        {'id': 'evaluateWeather1.output',        'type': 'object', 'description': 'Weather evaluation result',   'binding': {'nodeId': 'evaluateWeather1',       'outputId': 'output'}},
        {'id': 'evaluateWeather1.error',         'type': 'object', 'binding': {'nodeId': 'evaluateWeather1',     'outputId': 'error'}}
    ]
}

d['layout'] = {
    'nodes': {
        'start':                 {'position': {'x': 64,  'y': 144}},
        'fetchWeatherOpenMeteo1':{'position': {'x': 0,   'y': 0}},
        'evaluateWeather1':      {'position': {'x': 0,   'y': 0}},
        'end1':                  {'position': {'x': 0,   'y': 0}}
    }
}

with open('BellevueWeather.flow', 'w') as f:
    json.dump(d, f, indent=2)
print('Done')
EOF

